<?php
session_start();
require_once __DIR__ . '/conexion.php';
require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/schema_guard.php';
asegurarSistemaUsuarios($conexion);
exigirRoles(array('ADMINISTRADOR'));
if (strtoupper((string)($_SERVER['REQUEST_METHOD'] ?? 'GET')) === 'POST') automacValidarCsrf(true);
$conexion->set_charset('utf8mb4');

function mrE($valor){return htmlspecialchars((string)$valor,ENT_QUOTES,'UTF-8');}
function mrTablaExiste($conexion,$tabla){return esquemaTablaExiste($conexion,(string)$tabla);}

$mensaje='';$error='';
$tablasRequeridas=array('rescates_opciones','rescates_componentes','tipos_control','subtipos_control');
$faltan=array();
foreach($tablasRequeridas as $tabla)if(!mrTablaExiste($conexion,$tabla))$faltan[]=$tabla;
$tablasPerfilesRescate=mrTablaExiste($conexion,'rescates_compatibilidades')&&mrTablaExiste($conexion,'rescates_codigos_corriente')&&mrTablaExiste($conexion,'rescates_presentacion');

if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        $accion=(string)($_POST['accion']??'');
        if($faltan)throw new Exception('Faltan tablas base de rescates: '.implode(', ',$faltan).'.');
        if(!$tablasPerfilesRescate)throw new Exception('Falta aplicar migracion_perfiles_senalizacion_rescates_2026-10-01.sql.');
        if($accion==='guardar_rescate'){
            $id=(int)($_POST['rescate_id']??0);$clave=strtoupper(trim((string)($_POST['rescate_clave']??'')));$nombre=trim((string)($_POST['rescate_nombre']??''));$familia=strtoupper(trim((string)($_POST['rescate_familia']??'')));$orden=(int)($_POST['rescate_orden']??100);$activo=isset($_POST['rescate_activo'])?'SI':'NO';$modo=strtoupper(trim((string)($_POST['modo_precio']??'COMPONENTES')));$codigoPresentacion=strtoupper(trim((string)($_POST['codigo_presentacion']??'')));
            if($clave===''||$nombre===''||!in_array($familia,array('HIDRAULICO','MRL_IMAN'),true))throw new Exception('Complete clave, nombre y familia válidos.');
            if(!in_array($modo,array('COMPONENTES','ARTICULO_CORRIENTE'),true))throw new Exception('Modo de valorización inválido.');
            if($modo==='COMPONENTES'&&$codigoPresentacion==='')throw new Exception('Indique el código de presentación comercial configurado para el rescate.');
            if($modo==='ARTICULO_CORRIENTE')$codigoPresentacion='';
            $conexion->begin_transaction();
            try{
                $dupe=$conexion->prepare('SELECT rescate_id FROM rescates_opciones WHERE UPPER(TRIM(rescate_clave))=? AND rescate_id<>? LIMIT 1');$dupe->bind_param('si',$clave,$id);$dupe->execute();$hayDuplicado=$dupe->get_result()->num_rows>0;$dupe->close();if($hayDuplicado)throw new Exception('Ya existe un rescate con esa clave interna.');
                if($id>0){$st=$conexion->prepare('UPDATE rescates_opciones SET rescate_clave=?,rescate_nombre=?,rescate_familia=?,rescate_orden=?,rescate_activo=? WHERE rescate_id=?');$st->bind_param('sssisi',$clave,$nombre,$familia,$orden,$activo,$id);}
                else{$st=$conexion->prepare('INSERT INTO rescates_opciones(rescate_clave,rescate_nombre,rescate_familia,rescate_orden,rescate_activo) VALUES(?,?,?,?,?)');$st->bind_param('sssis',$clave,$nombre,$familia,$orden,$activo);}
                if(!$st||!$st->execute())throw new Exception($st?$st->error:$conexion->error);if($id<=0)$id=(int)$st->insert_id;$st->close();
                $st=$conexion->prepare('INSERT INTO rescates_presentacion(rescate_id,modo_precio,codigo_presentacion) VALUES(?,?,?) ON DUPLICATE KEY UPDATE modo_precio=VALUES(modo_precio),codigo_presentacion=VALUES(codigo_presentacion)');$st->bind_param('iss',$id,$modo,$codigoPresentacion);if(!$st->execute())throw new Exception($st->error);$st->close();
                $conexion->commit();$mensaje='Rescate y presentación guardados.';
            }catch(Throwable $e){$conexion->rollback();throw $e;}
        }elseif($accion==='guardar_presentacion'){
            $id=(int)($_POST['rescate_id']??0);$modo=strtoupper(trim((string)($_POST['modo_precio']??'')));$codigo=strtoupper(trim((string)($_POST['codigo_presentacion']??'')));
            if($id<=0||!in_array($modo,array('COMPONENTES','ARTICULO_CORRIENTE'),true))throw new Exception('Seleccione rescate y modo de valorización válidos.');
            if($modo==='COMPONENTES'&&$codigo==='')throw new Exception('La presentación por componentes requiere un código comercial de referencia.');if($modo==='ARTICULO_CORRIENTE')$codigo='';
            $st=$conexion->prepare('INSERT INTO rescates_presentacion(rescate_id,modo_precio,codigo_presentacion) VALUES(?,?,?) ON DUPLICATE KEY UPDATE modo_precio=VALUES(modo_precio),codigo_presentacion=VALUES(codigo_presentacion)');$st->bind_param('iss',$id,$modo,$codigo);if(!$st->execute())throw new Exception($st->error);$st->close();$mensaje='Presentación de rescate actualizada.';
        }elseif($accion==='guardar_compatibilidad'){
            $id=(int)($_POST['compatibilidad_id']??0);$rescate=(int)($_POST['rescate_id']??0);$tipo=(int)($_POST['tipo_control_id']??0);$subtipo=(int)($_POST['subtipo_control_id']??0);$corriente=(int)($_POST['corriente_clave']??0);$activo=isset($_POST['activo'])?'SI':'NO';$orden=(int)($_POST['orden']??100);
            if($rescate<=0||$tipo<=0)throw new Exception('Seleccione rescate y tipo de Control.');
            if($id>0){$st=$conexion->prepare('UPDATE rescates_compatibilidades SET rescate_id=?,tipo_control_id=?,subtipo_control_id=NULLIF(?,0),corriente_clave=NULLIF(?,0),activo=?,orden=? WHERE compatibilidad_id=?');$st->bind_param('iiiisii',$rescate,$tipo,$subtipo,$corriente,$activo,$orden,$id);}
            else{$st=$conexion->prepare('INSERT INTO rescates_compatibilidades(rescate_id,tipo_control_id,subtipo_control_id,corriente_clave,activo,orden) VALUES(?,?,NULLIF(?,0),NULLIF(?,0),?,?)');$st->bind_param('iiiisi',$rescate,$tipo,$subtipo,$corriente,$activo,$orden);}
            if(!$st||!$st->execute())throw new Exception($st?$st->error:$conexion->error);$st->close();$mensaje='Compatibilidad guardada.';
        }elseif($accion==='guardar_codigo_corriente'){
            $id=(int)($_POST['articulo_rescate_id']??0);$rescate=(int)($_POST['rescate_id']??0);$subtipo=(int)($_POST['subtipo_control_id']??0);$corriente=(int)($_POST['corriente_clave']??0);$codigo=strtoupper(trim((string)($_POST['codigo']??'')));$activo=isset($_POST['activo'])?'SI':'NO';$orden=(int)($_POST['orden']??100);
            if($rescate<=0||$subtipo<=0||$corriente<=0||$codigo==='')throw new Exception('Complete variador, corriente y código Bejerman.');
            if($id>0){$st=$conexion->prepare('UPDATE rescates_codigos_corriente SET rescate_id=?,subtipo_control_id=?,corriente_clave=?,codigo=?,activo=?,orden=? WHERE articulo_rescate_id=?');$st->bind_param('iiissii',$rescate,$subtipo,$corriente,$codigo,$activo,$orden,$id);}
            else{$st=$conexion->prepare('INSERT INTO rescates_codigos_corriente(rescate_id,subtipo_control_id,corriente_clave,codigo,activo,orden) VALUES(?,?,?,?,?,?)');$st->bind_param('iiissi',$rescate,$subtipo,$corriente,$codigo,$activo,$orden);}
            if(!$st||!$st->execute())throw new Exception($st?$st->error:$conexion->error);$st->close();$mensaje='Código Bejerman por variador y corriente guardado.';
        }elseif($accion==='guardar_componente'){
            $id=(int)($_POST['componente_id']??0);$rescate=(int)($_POST['rescate_id']??0);$codigo=strtoupper(trim((string)($_POST['componente_codigo']??'')));$regla=strtoupper(trim((string)($_POST['componente_regla']??'')));$cantidad=(float)str_replace(',','.',(string)($_POST['componente_cantidad']??'1'));$orden=(int)($_POST['componente_orden']??100);$activo=isset($_POST['componente_activo'])?'SI':'NO';
            if($rescate<=0||$codigo===''||$cantidad<=0||!in_array($regla,array('FIJO_POR_EQUIPO','PARADAS_MENOS_2'),true))throw new Exception('Complete código, cantidad y fórmula de componente válidos.');
            if($id>0){$st=$conexion->prepare('UPDATE rescates_componentes SET componente_codigo=?,componente_regla=?,componente_cantidad=?,componente_orden=?,componente_activo=? WHERE componente_id=? AND rescate_id=?');$st->bind_param('ssdisii',$codigo,$regla,$cantidad,$orden,$activo,$id,$rescate);}
            else{$st=$conexion->prepare('INSERT INTO rescates_componentes(rescate_id,componente_codigo,componente_regla,componente_cantidad,componente_orden,componente_activo) VALUES(?,?,?,?,?,?)');$st->bind_param('issdis',$rescate,$codigo,$regla,$cantidad,$orden,$activo);}
            if(!$st||!$st->execute())throw new Exception($st?$st->error:$conexion->error);$st->close();$mensaje='Componente de rescate guardado.';
        }else throw new Exception('Acción de mantenimiento no reconocida.');
    }catch(Throwable $e){$error=$e->getMessage();}
}

$tipos=array();$rt=$conexion->query('SELECT ctrltipo_id,ctrltipo_name FROM tipos_control ORDER BY ctrltipo_id');if($rt)while($x=$rt->fetch_assoc())$tipos[]=$x;
$subtipos=array();$rs=$conexion->query('SELECT ctrlsubtipo_id,ctrlsubtipo_name FROM subtipos_control ORDER BY ctrlsubtipo_name');if($rs)while($x=$rs->fetch_assoc())$subtipos[]=$x;
$rescates=array();$compatibilidades=array();$codigosCorriente=array();$componentes=array();
if(!$faltan){
    $r=$conexion->query("SELECT r.*,COALESCE(p.modo_precio,'COMPONENTES') modo_precio,COALESCE(p.codigo_presentacion,'') codigo_presentacion FROM rescates_opciones r LEFT JOIN rescates_presentacion p ON p.rescate_id=r.rescate_id ORDER BY r.rescate_familia,r.rescate_orden,r.rescate_id");if($r)while($x=$r->fetch_assoc())$rescates[]=$x;
    if($tablasPerfilesRescate){
        $r=$conexion->query('SELECT * FROM rescates_compatibilidades ORDER BY rescate_id,orden,compatibilidad_id');if($r)while($x=$r->fetch_assoc())$compatibilidades[]=$x;
        $r=$conexion->query('SELECT * FROM rescates_codigos_corriente ORDER BY rescate_id,orden,subtipo_control_id,corriente_clave');if($r)while($x=$r->fetch_assoc())$codigosCorriente[]=$x;
    }
    $r=$conexion->query('SELECT * FROM rescates_componentes ORDER BY rescate_id,componente_orden,componente_id');if($r)while($x=$r->fetch_assoc())$componentes[]=$x;
}
$preciosMap=array();if(mrTablaExiste($conexion,'lista_precios')){$r=$conexion->query('SELECT precios_codigo,precios_descripcion,precios_costo FROM lista_precios');if($r)while($x=$r->fetch_assoc())$preciosMap[strtoupper(trim((string)$x['precios_codigo']))]=$x;}
function mrBadge($codigo,$precios){$fila=$precios[strtoupper(trim((string)$codigo))]??null;if(!$fila)return '<span class="bad">NO EN LISTA COTIZADOR</span>';return (float)$fila['precios_costo']>0?'<span class="good">PRECIO DISPONIBLE</span>':'<span class="bad">PRECIO 0</span>';}
function mrOptions($filas,$pk,$texto,$seleccionado=0,$todos=false){$html=$todos?'<option value="0">Cualquier valor</option>':'';foreach($filas as $fila){$id=(int)$fila[$pk];$sel=$id===(int)$seleccionado?' selected':'';$html.='<option value="'.$id.'"'.$sel.'>'.mrE($fila[$texto]).'</option>';}return $html;}
?>
