<?php if($compatRes):?><div class="scroll"><table><thead><tr><th>Tipo</th><th>Subtipo</th><th>Corriente</th><th>Orden</th><th>Activa</th><th></th></tr></thead><tbody><?php foreach($compatRes as $c):?><tr><form method="post"><?=automacCsrfInput()?><input type="hidden" name="accion" value="guardar_compatibilidad"><input type="hidden" name="compatibilidad_id" value="<?=(int)$c['compatibilidad_id']?>"><input type="hidden" name="rescate_id" value="<?=$rid?>"><td><select name="tipo_control_id"><?=mrOptions($tipos,'ctrltipo_id','ctrltipo_name',(int)$c['tipo_control_id'])?></select></td><td><select name="subtipo_control_id"><?=mrOptions($subtipos,'ctrlsubtipo_id','ctrlsubtipo_name',(int)($c['subtipo_control_id']??0),true)?></select></td><td><input type="number" min="0" step="1" name="corriente_clave" value="<?=(int)($c['corriente_clave']??0)?>"></td><td><input type="number" name="orden" value="<?=(int)$c['orden']?>"></td><td><input type="checkbox" name="activo" <?=$c['activo']==='SI'?'checked':''?>></td><td><button class="btn">Guardar</button></td></form></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No hay reglas explícitas; el motor conserva el filtro histórico por familia hasta que se agreguen reglas.</p><?php endif;?></div>
<div class="section"><h3>Artículos directos por variador y corriente</h3><form method="post" class="grid"><?=automacCsrfInput()?><input type="hidden" name="accion" value="guardar_codigo_corriente"><input type="hidden" name="rescate_id" value="<?=$rid?>"><label>Variador / subtipo<select name="subtipo_control_id" required><?=mrOptions($subtipos,'ctrlsubtipo_id','ctrlsubtipo_name')?></select></label><label>Corriente (A)<input type="number" min="1" step="1" name="corriente_clave" required></label><label>Código Bejerman<input name="codigo" required></label><label>Orden<input type="number" name="orden" value="100"></label><label><input type="checkbox" name="activo" checked> Activo</label><button class="btn">Agregar artículo</button></form>
